#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""v13 manuscript generator (Data Descriptor) — every number read from the frozen v13 tables;
gene/sample values are looked up explicitly (never by row position)."""
import csv, os, re, statistics
V13=r"C:\Users\fengq\Desktop\EGFR\EGFR的v13"; R=os.path.join(V13,"results"); PK=os.path.join(V13,"dataset_package")
def rd(p):
    with open(p,encoding="utf-8-sig",newline="") as f: return list(csv.DictReader(f))
def one(rows, **kw):
    hit=[r for r in rows if all(str(r.get(k,""))==str(v) for k,v in kw.items())]
    assert len(hit)==1, f"expected exactly one row for {kw}, found {len(hit)}"
    return hit[0]
reg=rd(os.path.join(PK,"01_cohort_registry","cohort_registry.csv"))
cc=[r for r in reg if r["design"]=="case-control"]; ex=[r for r in reg if r["design"]!="case-control"]
n_cc=len(cc); n_assays=sum(int(r["n_assay_records"]) for r in cc)
n_pat=sum(int(r["n_unique_patients"]) for r in cc if str(r["n_unique_patients"]).isdigit())
n_paired=sum(1 for r in cc if r["paired_design_used"]=="yes"); n_nopid=sum(1 for r in cc if r["patient_identity_available"]=="no")
cov=rd(os.path.join(PK,"04_modules","platform_module_coverage.csv"))
inc={r["module"] for r in cov if int(r["n_present"])<int(r["n_members"])}
mod_cov={}
for r in cov: mod_cov[r["module"]]=min(mod_cov.get(r["module"],1.0), float(r["coverage"]))
worst=sorted(mod_cov.items(), key=lambda x: x[1])[:3]
pc_full=rd(os.path.join(R,"v13_percohort_effects_complete.csv"))
n_full=len(pc_full); n_est=sum(1 for r in pc_full if r["measure"] in ("SMDH","SMCRPH")); n_ne=n_full-n_est
ne=rd(os.path.join(R,"v13_not_estimable_pairs.csv"))
scc=rd(os.path.join(R,"v12_sc_comparisons.csv"))
sig=[r for r in scc if r["fdr"] not in ("","NA") and float(r["fdr"])<0.05]
tt={}
for r in scc: tt[r["test_used"]]=tt.get(r["test_used"],0)+1
ct={}
for r in scc: ct[r["comparison_type"]]=ct.get(r["comparison_type"],0)+1
mut=rd(os.path.join(R,"v12_escc_mutation_denominators.csv")); cna=rd(os.path.join(R,"v12_escc_cna_summary.csv"))
tp53=one(mut, gene="TP53"); egfr_m=one(mut, gene="EGFR"); kras=one(mut, gene="KRAS"); egfr_c=one(cna, gene="EGFR")
ph=rd(os.path.join(R,"v12_qc_cox_ph_assumption.csv"))
col=rd(os.path.join(R,"v13_qc_vif_by_predictor.csv"))
con=rd(os.path.join(R,"v13_qc_cross_cohort_consistency.csv"))
ccons=[r for r in con if int(r["k"])>=2]
same_sign=sum(1 for r in ccons if r["direction_consistent"].upper()=="TRUE")
sen=rd(os.path.join(R,"v13_qc_coverage_threshold_sensitivity.csv"))
def nsig(tag): return sum(1 for r in sen if r["scenario"]==tag and r["fdr"] not in ("","NA") and float(r["fdr"])<0.05)
def nk(tag): return sum(1 for r in sen if r["scenario"]==tag)
sigol=rd(os.path.join(R,"v13_qc_signature_overlap.csv"))
max_ov=max(float(r["frac_overlap_xcell"]) for r in sigol)
n_ov=sum(1 for r in sigol if float(r["frac_overlap_xcell"])>0.2)
inv=rd(os.path.join(PK,"08_qc","file_inventory_and_checksums.csv"))
sc_verify=rd(os.path.join(R,"v12_qc_module_score_effect_verification.csv"))
tcgascore=rd(os.path.join(R,"v12_qc_survival_score_verification.csv")); tcgacox=rd(os.path.join(R,"v12_qc_survival_cox_verification.csv"))
xcell=rd(os.path.join(R,"v12_qc_xcell_recompute_verification.csv"))
r2=[float(r["r2_overall"]) for r in col]; vif=[float(r["max_vif_predictor"]) for r in col]
r2_med=statistics.median(r2); vif_med=statistics.median(vif)   # sorted medians, never index[len//2]
cg=rd(os.path.join(R,"v12_common_gene_sensitivity_summary.csv"))
flagcol=[c for c in cg[0] if "flag" in c.lower()][0]
disagree=[r["module"] for r in cg if "direction disagreement" in str(r[flagcol])]
notscor=[r["module"] for r in cg if "insufficient" in str(r[flagcol])]
title="A curated cross-disease transcriptomic resource with growth-factor and tissue-composition annotations"
assert len(title)<=110
DEP="[DOI to be inserted after Zenodo deposit]"
md=f"""# {title}

**Abstract**
Growth-factor pathway modules are scored routinely in bulk tissue transcriptomes, yet scores from different studies are rarely comparable and each user repeats the same curation work. This resource reorganises public human tissue transcriptomes into a comparable, annotation-rich form. It contains {n_cc} case-control expression cohorts across ten contexts ({n_assays} assay records from 27 curated series of which 26 form the case-control resource, {n_pat} patients with available identifiers across those 26 cohorts, 12 platform annotations), sample-level annotation with tissue type, case-control role, paired relations and exclusion reasons, harmonised gene mapping with a transformation log, seventeen growth-factor module definitions with per-platform gene coverage, per-sample module scores, expression-derived composition scores with four compartments, donor-level and cell-level summaries from four single-cell datasets, a complete estimates layer that retains non-significant, not-estimable and not-testable results, validation records that separate exact reproduction from rank agreement, runnable reuse examples and the software environment. Scores are cohort-internal; cross-cohort comparison is supported through effect sizes, and the comparability of those effects is quantified rather than assumed. The resource is deposited with a persistent identifier.

**Background & Summary**
Module scores for RTK and growth-factor signalling are treated as if they measured a comparable quantity across studies, yet they do not: platforms differ in gene coverage, cohorts differ in tissue composition and design, and processed matrices differ in transformation history. A user who wants to test whether a module differs between tumour and normal tissue across diseases must first locate comparable series, resolve sample identity and tissue type, map probes to gene symbols, decide how to handle composition, and then repeat the exercise for the next cohort.

This resource performs that curation once, documents it, and quantifies how far it can be trusted. It provides (i) a cohort registry with design, platform, counts, origin publications and provenance; (ii) sample-level annotation including tissue type, case-control role, pairing and exclusion reasons; (iii) gene-mapping and transformation provenance for every cohort together with a runnable script that rebuilds one series from its public accession to module scores; (iv) module definitions with per-platform coverage and an explicit statement that a module measured with 33% of its members is not the same quantity as the full module; (v) per-sample module scores with a stated construction rule for each layer; (vi) expression-derived composition scores keyed by sample identifier, with a signature-overlap audit that bounds how far they can be treated as independent covariates; (vii) donor-level summaries from single-cell datasets with raw and curated labels kept separate; (viii) a complete estimates layer in which every cohort-by-module pair is accounted for, including the pairs that are not estimable and why; and (ix) validation records that state what was reproduced exactly, what was reproduced in rank order only, and what remains a sensitivity analysis.

**Methods**
*Cohort assembly and curation flow.* Public series were sought for ten contexts (lung adenocarcinoma, colorectal, gastric, pancreatic, hepatocellular and oesophageal squamous cancer; inflammatory bowel disease; chronic obstructive pulmonary disease; non-alcoholic fatty liver disease; asthma). A series entered the case-control resource only if case and control samples were measured on the same platform. Of the {len(reg)} series with processed matrices in this workspace, {n_cc} qualified as case-control cohorts and one ({ex['0' if False else 0]['accession']}, {ex[0]['n_assay_records']} samples, Responder versus NonResponder) was excluded because it is a treatment-response design; a further colorectal series (GSE39582) was analysed only as an external validation set from its public accession. The full screening and exclusion counts are shipped as 08_qc/curation_flow.csv. Paired designs are derived from sample metadata, not assumed: a cohort is analysed as paired when at least four patients contribute both a case and a control sample ({n_paired} cohorts, and {sum(int(r['patients_with_both_arms'] or 0) for r in cc if r['paired_design_used']=='yes')} patients in total); in paired cohorts only complete pairs enter the paired effect estimate, and the remaining samples are not pooled into it. {n_nopid} cohorts provide no patient identifiers, so pairing cannot be established and the analysis is unpaired by necessity, which is recorded per cohort.
*Expression processing.* Within each cohort, probes were mapped to gene symbols, multiple probes per gene were collapsed by the mean, unmappable probes were dropped and legacy symbols were updated where unambiguous. Matrices were log2-transformed where the input distribution indicated raw intensities; the observed distribution, the decision and the outcome are recorded per cohort in the transformation log. No cross-cohort merging or batch correction was performed.
*Module definitions, coverage and score construction.* Seventeen modules were defined a priori and frozen with a version identifier (module_version = v12.0-frozen-2026-09). Full membership is shipped together with per-platform coverage; coverage is incomplete in part of the cohorts, with the largest gaps in {'; '.join(f'{m} (minimum coverage {c:.2f})' for m,c in worst)}. Score construction is layer-specific and stated explicitly: in the TCGA layer a module score is the mean over module members of the per-gene z-score across patients (gene values log2(x+1), z-scored within the context, averaged per patient across genes, then averaged across members, requiring at least two members); in the bulk cohorts it is a GSVA value z-scored within the cohort; in the single-cell layer it is the mean of log-normalised member-gene expression per cell, averaged to donor means before testing. These three quantities are not interchangeable, and the recommended layer for each use case is listed in Supplementary Table S8.
*Effects and pooling.* For each cohort and module the effect is the standardized difference between case and control samples computed on the shared root-mean-square denominator sqrt((sd_case^2+sd_control^2)/2): SMDH for unpaired cohorts, SMCRPH with the cohort's empirical within-pair correlation for paired cohorts. Every cohort-by-module pair is present in the shipped estimates table: {n_est} pairs are estimated and {n_ne} are reported as not estimable with a reason ({'; '.join(sorted({r['reason'] for r in ne}))}). Across cohorts, effects are pooled per context and module with REML and the Hartung-Knapp adjustment; DerSimonian-Laird, ad hoc Knapp-Hartung, unpaired-only and fixed-correlation (rho = 0.5 and 0.7) analyses are shipped as sensitivity analyses, because paired cohorts carry smaller sampling variances and therefore more weight.
*Tissue composition.* Composition was estimated with xCell v1.1.0, which returns expression-derived enrichment scores rather than cell proportions; four aggregated compartments (epithelial, fibroblast, endothelial, immune) are shipped keyed by sample identifier, with the join audit. Two limitations are quantified rather than asserted away: the compartment scores and the module scores are computed from the same expression matrix, and every module shares genes with the xCell signature panel ({n_ov} of {len(sigol)} modules share more than 20% of their members; maximum {max_ov:.0%}), so the base-versus-adjusted comparison is a sensitivity analysis and not an attempt to isolate an independent composition effect; and because disease status and composition are themselves correlated (overall model R-squared median {r2_med:.2f}, maximum {max(r2):.2f}; per-predictor VIF median {vif_med:.2f}, maximum {max(vif):.2f}), adjustment in high-R-squared cohorts removes part of the disease contrast by construction. The base model is the primary specification; the adjusted model is reported alongside it for every state.
*Single-cell layers.* Four datasets contributed contrasts: colorectal cancer (tumour versus non-tumour tissue; 29 donors), inflammatory bowel disease (disease versus healthy donors; 18 donors), gastric cancer (tumour versus adjacent tissue and versus non-pathological donors; 59 donors) and asthma (allergic asthma versus control; 8 donors). One further dataset (lung adenocarcinoma, 117,266 cells) was reviewed and excluded because all cells come from tumour tissue and no control arm exists. Cell-level module scores were averaged to donor means per cell type and arm; arms required at least 3 donors, a paired signed-rank test was used when at least 5 donors contributed both arms, an unpaired test only when the arms were donor-disjoint, and comparisons satisfying neither condition were reported as not testable. Multiplicity was controlled by Benjamini-Hochberg within families defined by context x module x comparison type. Cells labelled malignant inside non-tumour samples (358 cells) are flagged, not reassigned.
*TCGA-derived layer.* Molecular data were reorganised for six cancer contexts. Because the oesophageal source study contains both adenocarcinoma and squamous carcinoma, the analysed layers were restricted to the squamous subset identified from patient-level histological annotation (96 patients; 94 with survival data); in this version the mutation-prevalence denominator was corrected accordingly, since it previously counted all 185 oesophageal profiles, whereas the expression, copy-number and survival layers were already squamous-restricted. Mutation status is reported only for samples present in the source study's mutation-profiled list, as 'mutation reported' or 'no mutation reported in the selected mutation data'; samples outside that list are labelled not assayed/unknown.
*Source versions and licences.* Source releases, accessions and licence notes are shipped (01_cohort_registry/source_versions.csv), and the single-cell inputs are identified by their CELLxGENE dataset versions and collections (CRC dataset_version_id 81bd8922-b69a-45ea-9b2a-032c480c0e37 in collection 1cbfb478-2c7f-4d15-b522-9f74e9fe52a8; IBD dataset_version_id 5e75dd8f-5c5f-4056-ade2-117748429022 in collection 7c7bd6c2-925b-4034-baab-620ef1b760e1; LUAD dataset_version_id 229e74ee-9b3e-4ab2-bddb-9eccbac85b48 in collection 0bebef1a-4607-4584-9070-dacf89a0d635; STAD dataset_version_id c10345ad-7e42-4a1b-ae78-d4d1547b8d06 in collection f11cb29c-b546-4738-9bd8-66ea621a7bd5), which were re-verified against the CELLxGENE API (cell counts and titles agree with the locally processed files). Derived data are released under CC-BY-4.0 by the authors of this resource; upstream data remain under the terms of the originating repositories (GEO series terms, TCGA/GDC open-access terms, CELLxGENE dataset terms), and no controlled-access data were used. Users redistributing source matrices must observe the upstream terms.
*Validation rules and thresholds.* Reported checks use explicit rules (Supplementary Table S5): common-gene sensitivity uses the module members present in every cohort, flags a module when the effect direction disagrees with full-member scoring in at least 20% of cohorts, and marks it not scorable when fewer than two members are shared, with modules sharing only two members flagged as low-information; proportional hazards is assessed with scaled Schoenfeld residuals in the age-adjusted model and flagged at p<0.05; exact reproduction means an absolute difference of zero in the recomputed statistic, whereas rank agreement is reported as a Spearman correlation and is never described as exact reproduction.

**Data Records**
The resource is deposited in Zenodo ({DEP}) and organised as ten folders: 01 cohort registry, provenance and source versions; 02 sample annotation; 03 expression provenance with the mapping and transformation log; 04 module definitions, coverage and per-sample scores; 05 composition scores with sample keys, join audit and signature overlap; 06 single-cell dataset audit, labels and donor-aware comparisons; 07 the complete estimates layer, including not-estimable and not-testable results; 08 quality-control records, validation evidence and the curation flow; 09 runnable reuse examples with expected outputs and a shipped demo matrix; 10 environment, run order and versioning. A file inventory with row counts and SHA-256 checksums is shipped ({len(inv)} files); the estimates layer contains {n_full} cohort-module rows ({n_est} estimated, {n_ne} not estimable with reasons). Figure legends are provided as a separate document; Tables 1 and Supplementary Tables S1-S9 are separate files.

**Technical Validation**
Coverage and composition of the resource are shown in Figure 1; the validation evidence is shown in Figures 2 and 3. Sample identity: no sample identifier is duplicated across the {n_cc} case-control cohorts, and every sample in the annotation resolves to a registry entry. Design: pairing is metadata-derived ({n_paired} paired cohorts) and the {n_nopid} cohorts without patient identifiers are analysed unpaired and flagged. Histology and mutation layer: the oesophageal layer is restricted to squamous histology ({tp53['denominator_n']} patients), where TP53 is reported mutated in {tp53['n_mutated_samples']} patients ({tp53['pct']}%), EGFR in {egfr_m['n_mutated_samples']} ({egfr_m['pct']}%), and neither KRAS nor ERBB2 in any patient of the profiled list; EGFR high-level amplification is present in {egfr_c['n_high_amp']} of {egfr_c['n_cna_profiled']} copy-number-profiled squamous patients ({egfr_c['pct_high_amp']}%, with gain or amplification in {egfr_c['n_gain_or_amp']}, {egfr_c['pct_gain']}%). Exact reproduction: the {len(sc_verify)} cohort-module effects and their standard errors of three independently recomputed bulk cohorts agreed with the shipped values to a maximum absolute difference of 0 ({len(set(r['accession'] for r in sc_verify))} cohorts; sample-level scores Spearman 1.00); refitting the Cox models from the shipped patient scores reproduced all {len(tcgacox)} shipped hazard ratios with a maximum absolute difference of 0 (LUAD, CRC and squamous oesophageal contexts, univariable and age-plus-stage). Rank agreement (not exact reproduction): rebuilding the TCGA patient-level scores from the gene-level table reproduced the shipped scores in rank order (Spearman {min(float(r['spearman']) for r in tcgascore):.2f}-0.98 across {sum(int(r['pairs']) for r in tcgascore):,} patient-module pairs), the residual absolute differences arising from the aggregation order, which is now stated explicitly in Methods. Composition: independently recomputed xCell compartment scores agreed with the shipped values (Pearson {min(float(r['pearson']) for r in xcell):.2f}-{max(float(r['pearson']) for r in xcell):.2f}, Spearman {min(float(r['spearman']) for r in xcell):.2f}-{max(float(r['spearman']) for r in xcell):.2f}). Comparability: across the {len(ccons)} context-module pairs with at least two cohorts, {same_sign} ({100*same_sign/len(ccons):.0f}%) have effects of the same sign in every contributing cohort, and the number of pooled states surviving BH control changes from {nsig('all cohorts')} with all cohorts to {nsig('coverage >= 0.60')} at coverage 0.60, {nsig('coverage >= 0.80')} at 0.80 and {nsig('coverage >= 0.90')} at 0.90 (k = {nk('all cohorts')} to {nk('coverage >= 0.90')} pairs), so comparability degrades gradually with coverage rather than being an all-or-nothing property. Survival layer: proportional hazards was not violated for any of the {len(ph)} tested module features, which is evidence of absence of a detectable violation rather than proof that the assumption holds. Single-cell: {len(scc)} comparisons are shipped ({ct.get('tumour-vs-adjacent',0)} tumour-versus-adjacent, {ct.get('case-vs-healthy',0)} case-versus-healthy, {ct.get('cell-identity',0)} cell-identity), each labelled with the test actually used ({tt.get('wilcoxon-signed-rank (paired donors)',0)} paired by donor, {tt.get('mann-whitney (donor-disjoint)',0)} donor-disjoint unpaired, {tt.get('mann-whitney (cell-identity; unpaired)',0)} cell-identity contrasts, {tt.get('not testable',0)} reported as not testable); {len(sig)} comparisons reach FDR below 0.05 within their context x module x comparison-type family and are descriptive rather than validated biology. Module scores are expression-derived and do not measure phosphorylation or pathway activity.{" Module coverage flags: " + ", ".join(disagree) + " show direction disagreement in at least 20% of cohorts and " + ", ".join(notscor) + " have too few shared members to re-score." if disagree or notscor else ""}

**Usage Notes**
Which layer to use (Supplementary Table S8): GSVA z-scores within a cohort for within-cohort contrasts; TCGA member-mean z-scores for patient-level comparisons across tumour contexts; single-cell member means for cell-type-resolved questions; composition scores only as descriptors or as a sensitivity-analysis covariate. Users should note that (i) scores are comparable within a cohort and across cohorts only as effect sizes, and the shipped consistency and coverage-sensitivity tables quantify how far that holds; (ii) module coverage must be checked before any cross-cohort comparison, and the common-gene flags identify modules that should not be compared across platforms; (iii) the three score layers must not be concatenated; (iv) composition scores are enrichment scores, not proportions, and share genes with the module scores, so adjusted coefficients should be read as sensitivity analyses; (v) the same disease label in different layers does not imply the same patients, and the resource is not a patient-level multi-omics resource; (vi) the survival, driver and single-cell analyses shipped here are exploratory and include negative and not-estimable results; (vii) cohorts without patient identifiers cannot be analysed as paired, and this is flagged rather than assumed. Maintenance: the resource carries a version number, and updates are published as new versions of the deposit so that earlier DOIs remain citable; the changelog records what changed between versions.

**Data Availability**
All source data are public and listed with accessions and origin publications in the cohort registry. The curated resource is deposited in Zenodo under a CC-BY-4.0 licence ({DEP}); the code repository is https://github.com/sushuqiong/cross-disease-transcriptomic-resource (renamed from egfr-pathway-context-atlas; the former URL redirects) and is archived in the deposit. No new human specimens were collected; new derived data (annotations, scores, quality-control and validation records, and estimates) were generated and are included in the deposit.

**Code Availability**
Analysis code, the frozen module configuration, the run order, the version file and the two reuse examples are provided in the repository and archived in the deposit; software versions are recorded in folder 10.

**Ethics statement**
This work uses only publicly available, de-identified data; no ethical approval or informed consent was required.

**Author Contributions**
S.S. designed the resource, curated cohorts and annotations, implemented the analysis, validation and quality-control pipeline, and wrote the manuscript.

**Competing Interests**
The author declares no competing interests.

**Acknowledgements and Funding**
The author thanks the authors of the source studies and the public data providers (GEO, TCGA/GDC via cBioPortal, CELLxGENE). No specific funding was received for this work.

**Figure captions**
**Figure 1. Resource overview.** (A) Module gene coverage by disease context (fraction of frozen module members present in each cohort's processed matrix); (B) assay records, unique patients with identifiers and paired patients per context; (C) single-cell datasets with the arms available in each, the lung dataset shown as excluded.
**Figure 2. Technical validation of the resource.** (A) documented exclusions, flags and non-testable comparisons; (B) the single-cell comparison design actually used, by test type; (C) the complete estimates layer including non-significant and not-estimable results; (D) common-gene sensitivity of module scoring with flagged modules marked; (E) collinearity between disease status and the four composition scores per cohort.
**Figure 3. Comparability and coupling checks.** (A) cross-cohort direction consistency per context-module pair; (B) coverage-threshold sensitivity of the pooled results; (C) signature overlap between module members and the xCell panel, and per-predictor VIF within the disease-status model.
"""
p=os.path.join(V13,"01_manuscript","DataDescriptor_v13.md"); open(p,"w",encoding="utf-8").write(md)
ab=re.search(r"\*\*Abstract\*\*(.*?)\*\*Background", md, re.S).group(1)
print("written:",p)
print("title chars:",len(title),"| abstract words:",len(re.findall(r'\S+',ab)))
print("cohorts:",n_cc,"| assays:",n_assays,"| patients:",n_pat,"| paired:",n_paired,"| no-pid:",n_nopid)
print("effects matrix:",n_full,"= estimated",n_est,"+ not estimable",n_ne)
print("consistency:",same_sign,"/",len(ccons),f"({100*same_sign/len(ccons):.0f}%) | coverage BH:",nsig('all cohorts'),nsig('coverage >= 0.60'),nsig('coverage >= 0.80'),nsig('coverage >= 0.90'))
print("TP53:",tp53['n_mutated_samples'],"/",tp53['denominator_n'],"| EGFR amp:",egfr_c['n_high_amp'],"/",egfr_c['n_cna_profiled'])
print("signature overlap: >20% in",n_ov,"of",len(sigol),"| max",max_ov)
